// Vectors generated by ../test_olight_mesh.py DUMMY keys via olight_mesh.py (seq 0x123456, dst 0x0040).
import 'dart:typed_data';
import 'package:flutter_test/flutter_test.dart';
import 'package:olight_sphere/mesh.dart';

void main() {
  final k = MeshKeys.fromJson('''{"nid": 44, "enc_key": "000102030405060708090a0b0c0d0e0f",
    "priv_key": "101112131415161718191a1b1c1d1e1f", "app_key": "202122232425262728292a2b2c2d2e2f"}''', src: 0x6100);

  String pdu(List<int> access) {
    final net = buildNetworkPdu(k, k.src, 0x40, accessEncrypt(k, 0x123456, k.src, 0x40, Uint8List.fromList(access)), 0x123456);
    return hex(proxyPdu(net));
  }

  test('aid', () => expect(k.aid, 49));
  test('onoff pdu', () => expect(pdu(onoffSet(true, 0)), '002cdfd461312dc8a9a1a245783f575902f8bdc5c1629c'));
  test('hsl pdu', () => expect(pdu(hslSet(50, 120, 96, 0x11)), '002c380e0b39004ba9a1a2450c3ed798844aa1929fb3f18ef6b041f4'));
  test('encodings', () {
    expect(hex(lightnessSet(100, 0x1F)), '824cffff1f');
    expect(hex(hslSet(50, 120, 96, 0x11)), '827600805555c2f511');
    expect(hex(modeWhite), 'c9d00700');
    expect(hex(scene7), 'c9d00701660407');
  });

  // Bulb -> phone: encrypt a status as the bulb would (src = bulb, dst = phone), then decode it.
  Uint8List fromBulb(List<int> access) {
    final net = buildNetworkPdu(k, 0x0040, k.src, accessEncrypt(k, 0x222, 0x0040, k.src, Uint8List.fromList(access)), 0x222);
    return net;
  }

  test('receive onoff status', () {
    final n = parseNetworkPdu(k, fromBulb([0x82, 0x04, 1]))!;
    expect(n.src, 0x40);
    final st = BulbStatus();
    expect(st.apply(accessDecrypt(k, n)!), true);
    expect(st.on, true);
  });
  test('receive hsl status + vendor report', () {
    final st = BulbStatus();
    st.apply(accessDecrypt(k, parseNetworkPdu(k, fromBulb([0x82, 0x78, 0x00, 0x80, 0x00, 0x55, 0xff, 0xff]))!)!);
    expect(st.hue!.round(), 120);
    expect(st.sat!.round(), 100);
    st.apply(accessDecrypt(k, parseNetworkPdu(k, fromBulb([0xCD, 0xD0, 0x07, 1, 102, 4, 7, 103, 2, 0, 0, 0, 87]))!)!);
    expect(st.workMode, 1);
    expect(st.scene, 7);
    expect(st.battery, 87);
  });
  test('wrong key / tamper rejected', () {
    final pdu = fromBulb([0x82, 0x04, 1]);
    pdu[pdu.length - 1] ^= 1;
    expect(parseNetworkPdu(k, pdu), isNull);
  });
}
